package org.transittr.tests;
import android.app.*;import android.content.*;import android.os.*;import java.lang.reflect.*;import java.util.*;
public final class EgoRailCheck extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}private void check(boolean ok,String m){if(!ok)throw new AssertionError(m);}
 public void onStart(){Bundle out=new Bundle();boolean pass=false;try{
 ClassLoader l=getTargetContext().getClassLoader();Class<?> data=l.loadClass("org.transittr.MetroData"),line=l.loadClass("org.transittr.JourneyData$RailLine"),station=l.loadClass("org.transittr.JourneyData$Station"),client=l.loadClass("org.transittr.EgoRailClient");ArrayList lines=(ArrayList)data.getMethod("lines",Context.class,Integer.TYPE).invoke(null,getTargetContext(),0);Method map=client.getDeclaredMethod("stationCode",line,String.class,Boolean.TYPE);map.setAccessible(true);int count=0;
 for(Object route:lines){String id=(String)line.getField("id").get(route);ArrayList stops=(ArrayList)line.getField("stations").get(route);for(Object stop:stops){String name=(String)station.getField("name").get(stop);String f=(String)map.invoke(null,route,name,Boolean.FALSE),b=(String)map.invoke(null,route,name,Boolean.TRUE);check(f.length()>0&&b.length()>0,"missing station code "+id+" "+name);if(id.equals("M4"))check(!f.equals(b),"M4 direction-specific station IDs");count++;}}check(count==83,"all Ankara station mappings");Object combined=l.loadClass("org.transittr.RailEstimator").getMethod("combinedAnkara",ArrayList.class).invoke(null,lines);ArrayList joined=(ArrayList)line.getField("stations").get(combined);check(joined.size()==34,"combined M1 M2 M3 has 34 stations");for(Object stop:joined){String name=(String)station.getField("name").get(stop);check(((String)map.invoke(null,combined,name,Boolean.FALSE)).length()>0,"combined station code");}
 Calendar date=Calendar.getInstance(TimeZone.getTimeZone("GMT+03:00"));date.clear();date.set(2026,10,12,20,0,0);long now=date.getTimeInMillis();String body="{\"status\":\"TRUE\",\"table\":[{\"kod\":\"M1\",\"tur\":\"HAFTA İÇİ\",\"saat\":\"19:58 20:03 23:59 00:05\"}]}";Method parse=client.getMethod("parseTimes",String.class,String.class,Long.TYPE);ArrayList result=(ArrayList)parse.invoke(null,body,"M1",Long.valueOf(now));check(result.size()==3,"future times including after midnight");check(((Long)result.get(0)).longValue()-now==180000,"source departure not interpolated");check(((Long)result.get(2)).longValue()-now==14700000,"midnight rollover");boolean rejected=false;try{parse.invoke(null,body,"NOPE",Long.valueOf(now));}catch(InvocationTargetException e){rejected=true;}check(rejected,"unmatched station must fail");final Activity a=startActivitySync(new Intent().setClassName("org.transittr","org.transittr.TransitActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));runOnMainSync(new Runnable(){public void run(){try{Field city=a.getClass().getDeclaredField("city"),screen=a.getClass().getDeclaredField("screen");city.setAccessible(true);screen.setAccessible(true);city.setInt(a,0);screen.setInt(a,1);Method build=a.getClass().getDeclaredMethod("build");build.setAccessible(true);build.invoke(a);}catch(Exception e){throw new RuntimeException(e);}}});waitForIdleSync();Field chosen=a.getClass().getDeclaredField("selectedRail");chosen.setAccessible(true);Object shown=chosen.get(a);check("M123".equals(line.getField("id").get(shown)),"combined metro selected");Method display=a.getClass().getDeclaredMethod("railDisplay",line);display.setAccessible(true);check("M1-M2-M3".equals(display.invoke(a,shown)),"combined metro display text");final Method dialog=a.getClass().getDeclaredMethod("showAnkaraStationArrivals",String.class);dialog.setAccessible(true);runOnMainSync(new Runnable(){public void run(){try{dialog.invoke(a,"Koru");}catch(Exception e){throw new RuntimeException(e);}}});Thread.sleep(10000);Bundle capture=new Bundle();capture.putString("stream","CAPTURE=EGO_METRO_STATION\n");sendStatus(1,capture);Thread.sleep(4500);Object live=client.getMethod("query",line,String.class,Long.TYPE).invoke(null,shown,"Koru",Long.valueOf(System.currentTimeMillis()));check(live.getClass().getField("successfulDirections").getInt(live)==2,"both EGO station timetable directions reachable: "+live.getClass().getField("text").get(live));for(Object route:lines){String routeId=(String)line.getField("id").get(route);if(!routeId.equals("M4")&&!routeId.equals("A1")&&!routeId.equals("B1"))continue;ArrayList routeStops=(ArrayList)line.getField("stations").get(route);String origin=(String)station.getField("name").get(routeStops.get(0));Object more=client.getMethod("query",line,String.class,Long.TYPE).invoke(null,route,origin,Long.valueOf(System.currentTimeMillis()));check(more.getClass().getField("successfulDirections").getInt(more)==2,routeId+" EGO directions: "+more.getClass().getField("text").get(more));}pass=true;out.putString("stream","PASS Android "+Build.VERSION.RELEASE+"; EGO rail station mappings="+count+"; exact source minutes, day and midnight handling\n");
 }catch(Throwable e){java.io.StringWriter w=new java.io.StringWriter();e.printStackTrace(new java.io.PrintWriter(w));out.putString("stream","FAIL "+w);}finish(pass?-1:0,out);}
}
